function makePresentation(id: string, tmpDir: string): PresentationMetadata {
  const mdFile = path.join(tmpDir, "slidev", `${id}.md`);
  return {
    id,
    title: id,
    sourcePath: `slidev/${id}.md`,
    sourceAbsolutePath: mdFile,
    url: `/slidev/${id}`,
    outputPath: path.join(tmpDir, ".docusaurus", "output", id),
    previewUrl: `/slidev/${id}/1`,
    category: "",
  };
}

function makeOptions(overrides: Partial<PluginOptions> = {}): PluginOptions {
  return {
    path: "./slidev",
    download: false,
    exportFormats: ["pdf"],
    routeBasePath: "/slidev",
    pageTitle: "Presentations",
    pageTagline: "Overview",
    id: "default",
    theme: "seriph",
    addons: [],
    buildTimeout: 120,
    verbose: false,
    maxParallelBuilds: 2,
    autoInstall: false,
    dryRun: false,
    ...overrides,
  };
}

function makeContext(tmpDir: string): BuildContext {
  return { siteDir: tmpDir, baseUrl: "/" };
}

describe("checkSlidevInstalled", () => {
  let tmpDir: string;

  beforeEach(() => {
    tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), "builder-test-"));
  });

  it("returns true when @slidev/cli exists in node_modules", () => {
    const slidevDir = path.join(tmpDir, "node_modules", "@slidev", "cli");
    fs.mkdirSync(slidevDir, { recursive: true });

    expect(checkSlidevInstalled(tmpDir)).toBe(true);
  });

  it("returns false when @slidev/cli is not installed", () => {
    expect(checkSlidevInstalled(tmpDir)).toBe(false);
  });

  it("finds @slidev/cli in parent directory (monorepo)", () => {
    const slidevDir = path.join(tmpDir, "node_modules", "@slidev", "cli");
    fs.mkdirSync(slidevDir, { recursive: true });
    const childDir = path.join(tmpDir, "apps", "docs");
    fs.mkdirSync(childDir, { recursive: true });

    expect(checkSlidevInstalled(childDir)).toBe(true);
  });
});

describe("buildAllPresentations", () => {
  let tmpDir: string;

  beforeEach(() => {
    tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), "builder-all-"));
  });

  it("returns all-success when no presentations to build", async () => {
    const { buildAllPresentations } = await import("../builder");
    const results = await buildAllPresentations([], makeOptions(), makeContext(tmpDir));
    expect(results).toHaveLength(0);
  });

  it("skips unchanged presentations with matching hash", async () => {
    // Create presentation source
    const slidevDir = path.join(tmpDir, "slidev");
    fs.mkdirSync(slidevDir, { recursive: true });
    const mdFile = path.join(slidevDir, "intro.md");
    fs.writeFileSync(mdFile, "---\ntitle: Intro\n---\n\n# Slide 1");

    const presentation = makePresentation("intro", tmpDir);
    const options = makeOptions();
    const context = makeContext(tmpDir);

    // First build — should build
    const { buildAllPresentations } = await import("../builder");
    const results1 = await buildAllPresentations([presentation], options, context);
    expect(results1).toHaveLength(1);

    // Create fake output so hasCachedOutput returns true
    const { getSlidevCacheDir } = await import("../../infrastructure/fs/fileSystem");
    const cacheDir = getSlidevCacheDir(tmpDir, "default");
    const outputDir = path.join(cacheDir, "output", "intro");
    fs.mkdirSync(outputDir, { recursive: true });
    fs.writeFileSync(path.join(outputDir, "index.html"), "<html></html>");

    // Second build with same content — should skip
    const results2 = await buildAllPresentations([presentation], options, context);
    expect(results2).toHaveLength(1);
    expect(results2[0].success).toBe(true);
  });

  it("invalidates cache when options change", async () => {
    const slidevDir = path.join(tmpDir, "slidev");
    fs.mkdirSync(slidevDir, { recursive: true });
    const mdFile = path.join(slidevDir, "talk.md");
    fs.writeFileSync(mdFile, "---\ntitle: Talk\n---\n\n# Slide 1");

    const presentation = makePresentation("talk", tmpDir);
    const context = makeContext(tmpDir);

    const { buildAllPresentations } = await import("../builder");
    const { getSlidevCacheDir } = await import("../../infrastructure/fs/fileSystem");
    const { loadHashManifest, saveHashManifest } = await import("../../infrastructure/fs/hashManifest");

    // Simulate a cached build with theme "seriph"
    const options1 = makeOptions({ theme: "seriph" });
    await buildAllPresentations([presentation], options1, context);
    const cacheDir = getSlidevCacheDir(tmpDir, "default");

    // Create fake output
    const outputDir = path.join(cacheDir, "output", "talk");
    fs.mkdirSync(outputDir, { recursive: true });
    fs.writeFileSync(path.join(outputDir, "index.html"), "<html></html>");

    // Save hash from first build
    const hashes = loadHashManifest(cacheDir);

    // Change theme — should invalidate cache
    const options2 = makeOptions({ theme: "apple-basic" });
    const { runSlidevBuild } = await import("../../infrastructure/process/buildRunner");
    const mockRun = vi.mocked(runSlidevBuild);
    mockRun.mockClear();

    await buildAllPresentations([presentation], options2, context);
    // With a different theme, the hash changes, so build should be triggered
    expect(mockRun).toHaveBeenCalled();
  });
});
